function accessType_to_str(access : MemoryAccessType(mem_payload)) -> string =
  match access {
    Load(_)                   => "R",
    Store(_)                  => "W",
    Atomic(_)                 => "RW",
    InstructionFetch()        => "X",
    CacheAccess(_)            => "C",
  }

function access_within(addr, bytes, region_width_exp) = {
  let mask : bits('width) = ~(zero_extend(ones(region_width_exp)));
  (addr & mask) == ((addr + (bytes - 1)) & mask)
}

function aes_decode_rcon(r : bits(4)) -> bits(32) = {
  assert(r <_u 0xA);
  match r {
    0x0 => 0x00000001,
    0x1 => 0x00000002,
    0x2 => 0x00000004,
    0x3 => 0x00000008,
    0x4 => 0x00000010,
    0x5 => 0x00000020,
    0x6 => 0x00000040,
    0x7 => 0x00000080,
    0x8 => 0x0000001b,
    0x9 => 0x00000036,
    _   => internal_error(__FILE__, __LINE__, "Unexpected AES r") // unreachable -- required to silence Sail warning
  }
}

function aes_mixcolumn_byte_fwd(so : bits(8)) -> bits(32) = {
  gfmul(so, 0x3) @ so @ so @ gfmul(so, 0x2)
}

function aes_mixcolumn_byte_inv(so : bits(8)) -> bits(32) = {
  gfmul(so, 0xb) @ gfmul(so, 0xd) @ gfmul(so, 0x9) @ gfmul(so, 0xe)
}

function aes_mixcolumn_fwd(x : bits(32)) -> bits(32) = {
  let s0 : bits (8) = x[ 7.. 0];
  let s1 : bits (8) = x[15.. 8];
  let s2 : bits (8) = x[23..16];
  let s3 : bits (8) = x[31..24];
  let b0 : bits (8) = xt2(s0) ^ xt3(s1) ^    (s2) ^    (s3);
  let b1 : bits (8) =    (s0) ^ xt2(s1) ^ xt3(s2) ^    (s3);
  let b2 : bits (8) =    (s0) ^    (s1) ^ xt2(s2) ^ xt3(s3);
  let b3 : bits (8) = xt3(s0) ^    (s1) ^    (s2) ^ xt2(s3);
  b3 @ b2 @ b1 @ b0 // Return value
}

function aes_mixcolumn_inv(x : bits(32)) -> bits(32) = {
  let s0 : bits (8) = x[ 7.. 0];
  let s1 : bits (8) = x[15.. 8];
  let s2 : bits (8) = x[23..16];
  let s3 : bits (8) = x[31..24];
  let b0 : bits (8) = gfmul(s0, 0xE) ^ gfmul(s1, 0xB) ^ gfmul(s2, 0xD) ^ gfmul(s3, 0x9);
  let b1 : bits (8) = gfmul(s0, 0x9) ^ gfmul(s1, 0xE) ^ gfmul(s2, 0xB) ^ gfmul(s3, 0xD);
  let b2 : bits (8) = gfmul(s0, 0xD) ^ gfmul(s1, 0x9) ^ gfmul(s2, 0xE) ^ gfmul(s3, 0xB);
  let b3 : bits (8) = gfmul(s0, 0xB) ^ gfmul(s1, 0xD) ^ gfmul(s2, 0x9) ^ gfmul(s3, 0xE);
  b3 @ b2 @ b1 @ b0 // Return value
}

