  if illegal_variable_width(vd, vm, SEW_widen, LMUL_pow_widen) |
     not(valid_reg_overlap(vs2, vd, LMUL_pow_widen, LMUL_pow)) |
     not(valid_vm_src_overlap(vm, vs2, SEW_widen))
  then return Illegal_Instruction();

