  let 'SEW     = get_sew();
  let LMUL_pow = get_lmul_pow();
  let num_elem = get_num_elem(LMUL_pow, SEW);

  if not(valid_reg_group(vs1, LMUL_pow)) |
     not(valid_reg_group(vs2, LMUL_pow)) |
     not(valid_reg_group(vd, LMUL_pow))
  then return Illegal_Instruction();

  assert(SEW == 32 | SEW == 64);

  let vs2_val = read_vreg(num_elem, SEW, LMUL_pow, vs2);
  let vs1_val = read_vreg(num_elem, SEW, LMUL_pow, vs1);
  let vd_val  = read_vreg(num_elem, SEW, LMUL_pow, vd);

  var w : vector(20, bits('SEW)) = vector_init(zeros());

  let eg_len   = (unsigned(vl) / 4);

  foreach (i from 0 to (eg_len - 1)) {
    assert(i * 4 + 3 < num_elem);

    w = [w with
      0  = vd_val[i*4],
      1  = vd_val[i*4+1],
      2  = vd_val[i*4+2],
      3  = vd_val[i*4+3],

      4  = vs2_val[i*4],
      9  = vs2_val[i*4+1],
      10 = vs2_val[i*4+2],
      11 = vs2_val[i*4+3],

