function clause execute ZICBOZ(rs1) = {
  // `cbo.zero` is unconditionally permitted: the `menvcfg` enable bit
  // gated a less-privileged mode's use of it, and there is no
  // less-privileged mode (R-15-049a, R-15-060).

  let rs1_val = X(rs1);
  let cache_block_size = 2 ^ plat_cache_block_size_exp;
  let access : MemoryAccessType(mem_payload) = CacheAccess(CB_zero());

  // Offset from rs1 to the beginning of the cache block. This is 0 if rs1
  // is aligned to the cache block, or negative if rs1 is misaligned.
  let negative_offset = (rs1_val & ~(zero_extend(ones(plat_cache_block_size_exp)))) - rs1_val;

  match get_transformed_data_addr(rs1, negative_offset, access, cache_block_size) {
    Ext_DataAddr_Error(e) => Ext_DataAddr_Check_Failure(e),
    Ext_DataAddr_OK(vaddr) => {
      // "An implementation may update the bytes in any order and with any granularity
      //  and atomicity, including individual bytes."
      //
      // This implementation does a single atomic write.
      //
      // vaddr is the aligned address, but errors report the address
      // that was encoded in the instruction. We subtract the negative
      // offset (add the positive offset) to get it, which here is
      // always rs1.
      let paddr = physical_address(vaddr);
      match mem_write_ea(paddr, cache_block_size, access, false, false) {
        Err(exc_addr, e) => {
          // Cache accesses should not get split.
          assert(exc_addr == paddr);
          memory_exception(vaddr - negative_offset, e)
        },
        Ok(_)  => {
          match mem_write_value(paddr, cache_block_size, zeros(), access, false, false) {
            Ok(true)  => RETIRE_SUCCESS,
            Ok(false) => internal_error(__FILE__, __LINE__, "store got false from mem_write_value"),
            Err(exc_addr, e) => {
              // Cache accesses should not get split.
              assert(exc_addr == paddr);
              memory_exception(vaddr - negative_offset, e)
            },
          }
        }
      }
    },
  }
}

