        FetchBytes_Ext_Error(e) => F_Ext_Error(e),
        FetchBytes_Exception(e) => F_Error(e, PC + 2),
        FetchBytes_Success(ihi) => F_Base(append(ihi, ilo)),
      },
  }
}

