float_decompose op = {
    match __size(op) {
      16 => struct float_bits { sign = op[15 .. 15], exp = op[14 .. 10], mantissa = op[9 .. 0] },
      32 => struct float_bits { sign = op[31 .. 31], exp = op[30 .. 23], mantissa = op[22 .. 0] },
      64 => struct float_bits { sign = op[63 .. 63], exp = op[62 .. 52], mantissa = op[51 .. 0] },
      ($[int_wildcard 128] _) => struct float_bits { sign = op[127 .. 127], exp = op[126 .. 112], mantissa = op[111 .. 0] }
    }
}

