function write_vxsat(vxsat_val: bits(1)) -> unit = {
  if vcsr[vxsat] != vxsat_val then {
    vcsr[vxsat] = vxsat_val;
    dirty_v_context();
  };
  csr_write_callback("vxsat", zero_extend(vcsr[vxsat]));
  csr_write_callback("vcsr", zero_extend(vcsr.bits));
}

