function zvk_check_encdec(EGW : nat, EGS : nat1) -> bool = {
  let LMUL_pow = get_lmul_pow();
  let LMUL_times_VLEN = if LMUL_pow < 0 then vlen / (2 ^ abs_int(LMUL_pow)) else (2 ^ LMUL_pow) * vlen;
  // The element-group start term is gone with `vstart` (R-15-039a): every
  // element group runs from zero, so only `vl` has to divide the group size.
  (unsigned(vl) % EGS == 0) & LMUL_times_VLEN >= EGW
}

