type.contents:
enum AtomicSupport = {
  AMONone,
  AMOSwap,
  AMOLogical,
  AMOArithmetic,
}

struct CoreClassTiming = {
  vmclear_cycles : timing_cycles_t,
  fence_t_cycles : timing_cycles_t,
}

struct CoreRosterEntry = {
  hartid    : core_hartid,
  class     : CoreClass,
  island    : core_island,
  pinned    : bool,
  fec_units : bool,
}

union ExecutionResult = {
  // Successfully retired.
  Retire_Success                 : unit,

  // The instruction is a compressed instruction, and should be
  // executed as an uncompressed instruction. This can be used
  // for non-compressed instructions too but we only support
  // one level of indirection. This avoids making the execute()
  // function recursive, which is helpful for some backends,
  // and allows Sail to generate faster C/C++ code by avoiding
  // reallocation.
  ExecuteAs                      : instruction,

  // An instruction such as WFI, WRS.{STO,NTO}
  // entered a wait state, which may or may not
  // retire depending on the configuration.
  Enter_Wait                     : WaitReason,

  // Did not retire for a standard reason.
  Illegal_Instruction            : unit,
  Trap                           : (sync_exception, xlenbits),

  // Did not retire for custom reason.
  Ext_CSR_Check_Failure          : unit,
  Ext_ControlAddr_Check_Failure  : ext_control_addr_error,
  Ext_DataAddr_Check_Failure     : ext_data_addr_error,
  Ext_XRET_Priv_Failure          : unit,
}

enum ExtContextPolicy = {
  ExtContext_Off,        // The extension is always off.
  ExtContext_TwoState,   // Legal values are Off and Dirty.
  ExtContext_FourState,  // Legal values are Off, Initial, Clean and Dirty.
}

union Ext_DataAddr_Check ('a : Type) = {
  Ext_DataAddr_OK : virtaddr,    // Address to use for the data access
  Ext_DataAddr_Error : 'a
}

union FetchBytes_Result('width : Int), 'width >= 0 = {
  FetchBytes_Ext_Error : ext_fetch_addr_error,
  FetchBytes_Exception : ExceptionType,
  FetchBytes_Success   : bits('width * 8),
}

union FetchResult = {
  F_Ext_Error : ext_fetch_addr_error,      // For extensions
  F_Base      : word,                      // Base ISA
  F_RVC       : half,                      // Compressed ISA
  F_Error     : (ExceptionType, xlenbits)  // standard exception and PC
}

struct GlobalMisalignedExceptions = {
  load_store : option(misaligned_exception),
  vector     : option(misaligned_exception),
  amo        : option(misaligned_exception),
}

union HartState = {
  HART_ACTIVE  : unit,
  // The instruction that caused the wait. This is needed
  // because WFI can time out and cause an illegal instruction
  // exception so we need to know what to write to mtval.
  HART_WAITING : (WaitReason, instbits),
}

bitfield Mcause : xlenbits = {
  IsInterrupt : xlen - 1,
  Cause       : xlen - 2 .. 0
}

enum MemorySequencerOutcome = {
  // The pass drained its banks and the single completion read was positive.
  Seq_Confirmed,
  // The single completion read was negative. The transition stops here and the
  // domain does not enter the mode (R-15-189n, R-15-247f).
  Seq_FailStop,
  // The fail-stop is already latched, or the composition has no sequencer. Both
  // are refusals to act rather than results, and neither is a retry.
  Seq_Stopped,
}

bitfield Minterrupts : xlenbits = {
  MTI  : 7,  // Timer interrupt
}

enum MonotonicCounter = {
  Counter_ImageSecurityVersion,  // the base-image security-version floor (R-09-028)
  Counter_SealingRootVersion,    // the key-wrapping and sealing-root version (R-09-023)
  Counter_CredentialAttempt,     // the credential attempt-counter version (R-12-017)
  Counter_FreshnessEpoch,        // the durable-state freshness-epoch root (R-10-013c)
}

bitfield Mtvec : xlenbits = {
  Base : xlen - 1 .. 2,
  Mode : 1 .. 0
}

struct NoiseSample = {
  source : range(0, rot_max_noise_sources - 1),
  bits64 : bits(64),
}

struct PMA = {
  mem_type         : MemoryRegionType,
  // These have no effect on the model currently.
  cacheable        : bool,
  coherent         : bool,
  // If false then attempting to access this PMA during instruction fetch
  // will cause a fetch access fault.
  executable       : bool,
  // If false when reading/writing for data access then this will cause
  // an access fault.
  readable         : bool,
  writable         : bool,
  read_idempotent  : bool,
  write_idempotent : bool,
  // Misaligned handling for various accesses.
  misaligned_exceptions : PMAMisalignedExceptions,
  atomic_support   : AtomicSupport,
  // Flags whether this memory supports CBO.zero. Note that main memory regions must
  // have this set.
  supports_cbo_zero : bool,
  // The size of the optional misaligned atomicity granule is 2^misaligned_atomicity_granule_exp.
  // The value of 0 is used to indicate the attribute is absent.
  misaligned_atomicity_granule_size_exp : mag_size_exp,
  // The same as above but for vector accesses.
  vector_misaligned_atomicity_granule_size_exp : mag_size_exp,
  // Which of the two static latency classes this region is placed on
  // (core/memory_class.sail, R-15-247). It is `None` for IO memory and
  // `Some` for main memory, and the validator holds both directions: the
  // classes are two media, so a device endpoint is on neither and an array
  // is on exactly one. Placement is the static memory plan's composition-time
  // act, so this is a declaration and never a runtime property; nothing
  // reads it on any access path.
  memory_class : option(MemoryClass),
  // The datapath whose **software-managed scratchpad** this region is, or
  // `None` for every ordinary region (core/core_class.sail, R-15-165,
  // R-15-167).
  //
  // **A scratchpad is a region class and not a structure**, which is the whole
  // of what the model can carry about one. R-15-167 makes it capability-governed
  // plain memory at a fixed address range: no fill, no eviction, no valid or tag
  // array, and no lookup that is not the ordinary address decode, so it is
  // *declared* here beside every other property the composition fixes about an
  // address range rather than modeled as a second memory. R-15-165's test is
  // what that buys: the contents are a function of an explicit software
  // placement and never of access history, and it is history-dependence and not
  // address-indexing that carries the channel.
  //
  // **It is on neither main-memory latency class, and that is a placement fact
  // rather than an omission.** R-15-247's two classes are two media of *main*
  // memory; a scratchpad is the local tier above them, which R-15-168 says
  // scalar cores do not have at all. So `memory_class` is `None` here where it
  // is `Some` on every other array, and the validator holds the pair in both
  // directions rather than leaving a scratchpad to read as an unplaced array
  // (postlude/validate_config.sail).
  //
  // **Whose it is, is carried rather than derived.** R-15-165 places scratchpads
  // on the V- and M-class datapaths and R-15-113 sizes each class's in the class
  // table, so a region naming its class is what lets the two be held against
  // each other: a declared range whose size is not the class's declared
  // `scratchpad_bytes` is a composition describing two different scratchpads,
  // and neither artifact alone can see it.
  //
  // **Nothing on any access path reads it**, for the reason `memory_class`
  // states next door: the region is ordinary capability-governed memory, and
  // R-08-003's checks reach it unchanged, so a load or store that consulted this
  // field would be a machine deciding at run time what the memory plan decided
  // at composition. Its readers are the validator, the generated devicetree, the
  // `vmclear` pass R-07-014c defines over it, and the model's own properties.
  scratchpad : option(CoreClass),
  // TODO: Memory Ordering PMA
}

struct PMAMisalignedExceptions = {
  load_store : option(misaligned_exception),
  vector     : option(misaligned_exception),
  amo        : misaligned_exception,
}

struct PMA_Region = {
  // TODO: These should be physaddrbits, but currently that doesn't work due to a compiler bug:
  // https://github.com/rems-project/sail/issues/1392
  base       : bits(64),
  size       : bits(64),
  attributes : PMA,
  // If set to `false` this will be excluded from the generated device tree.
  // This doesn't affect Sail's execution at all; it's just a convenience
  // for generating a device tree that matches the PMAs.
  include_in_device_tree : bool,
}

struct Phys_Mem_Access_Info = {
  // Whether the access should be split.
  splittable : Splittability,
  // The granule size to use for any splitting.
  granule_size_exp : mag_size_exp,
}

enum Privileged_ISA_Version = {
  // commit f467e5dfd4acb4391870b8bfcfd687a0e5d8eddc (tag: Ratified-IMFDQC-and-Priv-v1.11)
  Privileged_ISA_1_11,
  // commit 75b2fbbdd783d539da69826fc3c11478b070c10b
  Privileged_ISA_1_12,
  // commit 2c07aa2bcc02fd5fb2e53e42a32dc62a3eb0aa62 (tag: riscv-isa-release-2c07aa2-2024-10-18)
  Privileged_ISA_1_13,
}

bitfield RVFI_DII_Execution_Packet_Ext_Integer : bits(320) = {
  magic : 63 .. 0, // must be "int-data"
  // rvfi_rd_wdata is the value of the x register addressed by rd after
  // execution of this instruction. This output must be zero when rd is zero.
  rvfi_rd_wdata  : 127 ..  64,
  // rvfi_rs1_rdata/rvfi_rs2_rdata is the value of the x register addressed
  // by rs1/rs2 before execution of this instruction. This output must be
  // zero when rs1/rs2 is zero.
  rvfi_rs1_rdata  : 191 .. 128,
  rvfi_rs2_rdata  : 255 .. 192,
  // rvfi_rd_addr is the decoded rd register address for the retired
  // instruction. For an instruction that writes no rd register, this output
  // must always be zero.
  rvfi_rd_addr      : 263 .. 256,
  // rvfi_rs1_addr and rvfi_rs2_addr are the decoded rs1 and rs1 register
  // addresses for the retired instruction. For an instruction that reads no
  // rs1/rs2 register, this output can have an arbitrary value. However, if
  // this output is nonzero then rvfi_rs1_rdata must carry the value stored
  // in that register in the pre-state.
  rvfi_rs1_addr  : 271 .. 264,
  rvfi_rs2_addr  : 279 .. 272,
  // The validity tag of the value written to rd. A register here holds a
  // capability, so the integer half of a register write is not the whole of it
  // (R-15-007i); this is the bit that closes the difference, taken from the
  // packet's padding rather than from a field with a meaning (M0.12).
  rvfi_rd_tag  : 280,
  padding  : 319 .. 281,
}

bitfield RVFI_DII_Execution_Packet_Ext_MemAccess : bits(704) = {
  magic : 63 .. 0, // must be "mem-data"
  // rvfi_mem_rdata is the pre-state data read from rvfi_mem_addr.
  // rvfi_mem_rmask specifies which bytes are valid.
  // CHERI-extension: widened to 32 bytes to allow reporting 129 bits
  rvfi_mem_rdata : 319 ..  64,
  // rvfi_mem_wdata is the post-state data written to rvfi_mem_addr.
  // rvfi_mem_wmask specifies which bytes are valid.
  // CHERI-extension: widened to 32 bytes to allow reporting 129 bits
  rvfi_mem_wdata : 575 .. 320,
  // rvfi_mem_rmask is a bitmask that specifies which bytes in rvfi_mem_rdata
  // contain valid read data from rvfi_mem_addr.
  // CHERI-extension: we extend rmask+wmask to 32 bits to allow reporting the
  // mask for CHERI/RV128 accesses here.
  rvfi_mem_rmask      : 607 .. 576,
  // rvfi_mem_wmask is a bitmask that specifies which bytes in rvfi_mem_wdata
  // contain valid data that is written to rvfi_mem_addr.
  // CHERI-extension: widened to 32 bits
  rvfi_mem_wmask      : 639 .. 608,
  // For memory operations (rvfi_mem_rmask and/or rvfi_mem_wmask are
  // non-zero), rvfi_mem_addr holds the accessed memory location.
  rvfi_mem_addr : 703 .. 640,
}

bitfield RVFI_DII_Execution_Packet_InstMetaData : bits(192) = {
  // The rvfi_order field must be set to the instruction index. No indices
  // must be used twice and there must be no gaps. Instructions may be
  // retired in a reordered fashion, as long as causality is preserved
  // (register and memory write operations must be retired before the read
  // operations that depend on them).
  rvfi_order  : 63 .. 0,
  // rvfi_insn is the instruction word for the retired instruction. In case
  // of an instruction with fewer than ILEN bits, the upper bits of this
  // output must be all zero. For compressed instructions the compressed
  // instruction word must be output on this port. For fused instructions the
  // complete fused instruction sequence must be output.
  rvfi_insn  : 127 ..  64,
  // rvfi_trap must be set for an instruction that cannot be decoded as a
  // legal instruction, such as 0x00000000.
  // In addition, rvfi_trap must be set for a misaligned memory read or
  // write in PMAs that don't allow misaligned access, or other memory
  // access violations. rvfi_trap must also be set for a jump instruction
  // that jumps to a misaligned instruction.
  rvfi_trap  : 135 ..  128,
  // The signal rvfi_halt must be set when the instruction is the last
  // instruction that the core retires before halting execution. It should not
  // be set for an instruction that triggers a trap condition if the CPU
  // reacts to the trap by executing a trap handler. This signal enables
  // verification of liveness properties.
  rvfi_halt  : 143 ..  136,
  // rvfi_intr must be set for the first instruction that is part of a trap
  // handler, i.e. an instruction that has a rvfi_pc_rdata that does not
  // match the rvfi_pc_wdata of the previous instruction.
  rvfi_intr  : 151 ..  144,
  // rvfi_mode must be set to the current privilege level, using the following
  // encoding: 0=U-Mode, 1=S-Mode, 2=Reserved, 3=M-Mode
  rvfi_mode  : 159 ..  152,
  // rvfi_ixl must be set to the value of MXL/SXL/UXL in the current privilege level,
  // using the following encoding: 1=32, 2=64
  rvfi_ixl  : 167 ..  160,

  // When the core retires an instruction, it asserts the rvfi_valid signal
  // and uses the signals described below to output the details of the
  // retired instruction. The signals below are only valid during such a
  // cycle and can be driven to arbitrary values in a cycle in which
  // rvfi_valid is not asserted.
  rvfi_valid  : 175 ..  168,
  // Note: since we only send these packets in the valid state, we could
  // omit the valid signal, but we need 3 bytes of padding after ixl anyway
  // so we might as well include it
  padding  : 191 ..  176,
}

bitfield RVFI_DII_Execution_Packet_PC : bits(128) = {
  // This is the program counter (pc) before (rvfi_pc_rdata) and after
  // (rvfi_pc_wdata) execution of this instruction. I.e. this is the address
  // of the retired instruction and the address of the next instruction.
  rvfi_pc_rdata  : 63 .. 0,
  rvfi_pc_wdata  : 127 ..  64,
}

bitfield RVFI_DII_Instruction_Packet : bits(64) = {
   padding   : 63 .. 56, // [7]
   rvfi_cmd  : 55 .. 48, // [6] This token is a trace command.  For example, reset device under test.
   rvfi_time : 47 .. 32, // [5 - 4] Time to inject token.  The difference between this and the previous
                         // instruction time gives a delay before injecting this instruction.
                         // This can be ignored for models but gives repeatability for implementations
                         // while shortening counterexamples.
   rvfi_insn : 31 ..  0, // [0 - 3] Instruction word: 32-bit instruction or command. The lower 16-bits
                         // may decode to a 16-bit compressed instruction.
}

